css:
/* Read by the PDF maker: the wide table fits a landscape A4 page. */
.print-format { orientation: Landscape; margin-left: 8mm; margin-right: 8mm; margin-top: 8mm; margin-bottom: 8mm; }
.print-format { max-width: none; padding: 0; }
.annexure-1 { font-size: 10px; color: #000; }
.annexure-1 .ann-tag { text-align: right; font-size: 10px; }
.annexure-1 .ann-title { text-align: center; font-size: 14px; font-weight: bold; margin: 2px 0 6px; }
.annexure-1 .ann-table { width: 100%; border-collapse: collapse; }
/* Over the standard print styles (cell padding, grey headers). */
.print-format .annexure-1 .ann-table td, .print-format .annexure-1 .ann-table th {
	border: 1px solid #000 !important; padding: 2px 4px !important; vertical-align: middle !important;
	color: #000 !important; background: none !important; font-size: 10px; line-height: 1.25; text-transform: none; }
.annexure-1 .ann-head { margin-bottom: -1px; }
.annexure-1 .ann-head .lbl { font-size: 9px; white-space: nowrap; }
.annexure-1 .ann-head .val { font-weight: 600; }
.annexure-1 .ann-body th { text-align: center; font-weight: bold; }
.annexure-1 .ann-body th.agency { width: 13%; }
.annexure-1 .group { text-align: center; font-weight: bold; width: 18px; line-height: 1.3; }
.annexure-1 .sl { text-align: center; width: 34px; }
.annexure-1 .particulars.center { text-align: center; }
.annexure-1 .sub { text-align: center; width: 40px; }
.annexure-1 .num { text-align: right; white-space: nowrap; }
.annexure-1 tr.bold td { font-weight: bold; }
.annexure-1 .total { font-weight: 600; }
.annexure-1 .ann-line { margin: 5px 0 0; }
.annexure-1 .ann-cert { font-style: italic; }
.annexure-1 .ann-sign { width: 100%; margin-top: 10px; border-collapse: separate; border-spacing: 16px 0; }
.print-format .annexure-1 .ann-sign td { border: 1px solid #000; width: 50%; padding: 6px; text-align: center; vertical-align: bottom; }
.annexure-1 .sign-space { height: 34px; }
.annexure-1 .sign-name { font-weight: 600; min-height: 14px; }
.annexure-1 .sign-label { border-top: 1px dashed #000; margin-top: 4px; padding-top: 2px; }
